"use client";
import AppShell from "@/components/AppShell";
import { studentGradeRows } from "@/lib/data";
export default function MahasiswaNilai(){const avg=Math.round(studentGradeRows.reduce((s,r)=>s+Number(r[1]),0)/studentGradeRows.length);return <AppShell><div className="page"><div className="page-heading"><div><h1 className="page-title">Rekap Nilai</h1><p className="page-subtitle">Rekap nilai terbaru dari Dosen dan Asisten Dosen.</p></div><span className="badge blue">Gasal 2026/2027</span></div><div className="grid-4"><div className="card score-card"><div className="score">{avg}</div><div className="score-label">Rata-rata</div></div><div className="card score-card"><div className="score">A</div><div className="score-label">Predikat sementara</div></div><div className="card score-card"><div className="score">{studentGradeRows.filter(r=>r[2]==="Dosen").length}</div><div className="score-label">Komponen Dosen</div></div><div className="card score-card"><div className="score">{studentGradeRows.filter(r=>r[2]==="Asisten").length}</div><div className="score-label">Komponen Asisten</div></div></div><div className="card" style={{marginTop:20}}><h2 className="section-title">Detail Nilai</h2><p className="section-subtitle">Nilai berubah mengikuti input terakhir yang dipublikasikan.</p><div className="table-wrap"><table><thead><tr><th>Komponen</th><th>Nilai</th><th>Pemberi Nilai</th><th>Status</th></tr></thead><tbody>{studentGradeRows.map(([name,score,owner])=><tr key={String(name)}><td>{name}</td><td><b>{score}</b></td><td>{owner}</td><td><span className="badge green">Tersedia</span></td></tr>)}</tbody></table></div></div></div></AppShell>}
